// Tabs (arrow keys move between them) and a copy button that says so.
export default function init(root) {
  const tabs = [...root.querySelectorAll('[role=tab]')], said = root.querySelector('.cta-install-said');
  const pick = (t, focus) => {
    tabs.forEach((b) => { const on = b === t; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; root.querySelector('#' + b.getAttribute('aria-controls')).hidden = !on; });
    if (focus) t.focus();
  };
  const onTab = (e) => { const t = e.target.closest('[role=tab]'); if (t) pick(t); };
  const onKey = (e) => {
    const i = tabs.indexOf(document.activeElement); if (i < 0) return;
    if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { e.preventDefault(); pick(tabs[(i + (e.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length], true); }
  };
  const onCopy = async (e) => {
    const b = e.target.closest('.cta-install-copy'); if (!b) return;
    const txt = b.parentNode.querySelector('code').textContent;
    let ok = false;
    try { await navigator.clipboard.writeText(txt); ok = true; } catch (_) {
      const r = document.createRange(); r.selectNodeContents(b.parentNode.querySelector('code'));
      const s = getSelection(); s.removeAllRanges(); s.addRange(r);
      try { ok = document.execCommand('copy'); } catch (__) { ok = false; }
    }
    b.textContent = ok ? 'Copied' : 'Press ⌘C'; said.textContent = ok ? 'Copied to the clipboard' : '';
    clearTimeout(b._t); b._t = setTimeout(() => { b.textContent = 'Copy'; said.textContent = ''; }, 2000);
  };
  root.addEventListener('click', onTab); root.addEventListener('click', onCopy); root.addEventListener('keydown', onKey);
  return () => { root.removeEventListener('click', onTab); root.removeEventListener('click', onCopy); root.removeEventListener('keydown', onKey); };
}

/* StyleFeatures scaffolds: shared runtime. Safe to load twice.
   - [data-reveal] fades in on scroll
   - .ph-video gets a play/pause button, a running timeline and a timecode, so a video slot behaves like one
     (data-dur="12" seconds, data-autoplay for background loops)
   - press N (or ?clean in the URL) to hide the notes */
if (!window.__sfScaffold) {
  window.__sfScaffold = true;
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); } }),
    { rootMargin: '0px 0px -8% 0px', threshold: 0.06 });
  const PLAY = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M6 3.8v12.4L16 10z" fill="currentColor"/></svg>';
  const PAUSE = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5.5 4h3v12h-3zM11.5 4h3v12h-3z" fill="currentColor"/></svg>';
  const fmt = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

  function video(el) {
    if (el.__sf) return; el.__sf = true;
    const dur = +el.dataset.dur || 12, loop = el.hasAttribute('data-autoplay') || el.hasAttribute('data-loop');
    const btn = document.createElement('button');
    btn.className = 'ph-play'; btn.type = 'button'; btn.setAttribute('aria-label', 'Play video'); btn.innerHTML = PLAY;
    const bar = document.createElement('div'); bar.className = 'ph-bar'; bar.setAttribute('aria-hidden', 'true');
    bar.innerHTML = `<span class="t">0:00</span><span class="ph-track"><i></i></span><span>${fmt(dur)}</span>`;
    if (el.hasAttribute('data-nobar')) bar.hidden = true;
    if (el.hasAttribute('data-nobutton')) btn.hidden = true;
    el.append(btn, bar);
    const t = bar.querySelector('.t');
    let pos = 0, playing = false, last = 0, raf = 0, visible = true;
    const draw = () => { el.style.setProperty('--p', pos / dur); t.textContent = fmt(pos); el.style.setProperty('--sf-t', pos); };
    const tick = (now) => {
      if (!playing) return;
      pos += Math.min(.1, (now - last) / 1000); last = now;
      if (pos >= dur) { if (loop) pos = 0; else { pos = dur; set(false); } }
      draw(); el.dispatchEvent(new CustomEvent('sf:time', { detail: { t: pos, dur } }));
      if (visible) raf = requestAnimationFrame(tick);
    };
    function set(on) {
      playing = on; el.classList.toggle('is-playing', on);
      btn.innerHTML = on ? PAUSE : PLAY; btn.setAttribute('aria-label', on ? 'Pause video' : 'Play video');
      cancelAnimationFrame(raf);
      if (on) { if (pos >= dur) pos = 0; last = performance.now(); raf = requestAnimationFrame(tick); }
    }
    btn.addEventListener('click', (e) => { e.stopPropagation(); set(!playing); });
    el.sfVideo = { play: () => set(true), pause: () => set(false), seek: (s) => { pos = Math.max(0, Math.min(dur, s)); draw(); }, get t() { return pos; }, dur };
    new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible && playing) { last = performance.now(); cancelAnimationFrame(raf); raf = requestAnimationFrame(tick); } }).observe(el);
    if (el.hasAttribute('data-autoplay') && !reduce) set(true);
    draw();
  }

  const scan = (root = document) => {
    root.querySelectorAll('[data-reveal]:not(.is-in)').forEach((el) => (reduce ? el.classList.add('is-in') : io.observe(el)));
    root.querySelectorAll('.ph-video').forEach(video);
  };
  window.sfScan = scan;
  window.sfVideo = video;
  const boot = () => scan();
  if (document.readyState === 'loading') addEventListener('DOMContentLoaded', boot); else boot();
  if (location.search.includes('clean')) document.documentElement.classList.add('sf-clean');
  if (location.search.includes('thumb')) document.documentElement.classList.add('sf-thumb');
  if (innerWidth < 700) addEventListener('DOMContentLoaded', () => document.querySelector('.sf-spec')?.classList.add('is-min'));
  addEventListener('keydown', (e) => { if (e.key === 'n' && !/INPUT|TEXTAREA/.test(document.activeElement?.tagName)) document.documentElement.classList.toggle('sf-clean'); });
  const down = () => document.documentElement.classList.toggle('is-down', scrollY > 24);
  addEventListener('scroll', down, { passive: true }); down();
}

/* playground.js: the part the film and the visitor share. Don't edit; describe your product in machine.js.

   machine.js names every action the product can take (open the dialog, create, share…): which element it's on,
   which states it's allowed in, and the side steps (show, hide, set, tween, type) that change the screen.
   The film says act('open') where a plain script would say click('@new'), show('@modal'); the visitor clicks
   the same element and gets the same steps. So whatever the tour shows, the visitor can do, and nothing else.

   The visitor's turn is a script too: each click appends that action's steps at the current moment and the
   engine plays on from there (tour.load), so the visitor gets the same eases, timings and camera as the film. */
import { zoom, unzoom } from '../tour/tour.js';

/* in a film script: do this action. Options go to its pointer step ({ dur, aim, wait }); { pointer: 'dblclick' } or
   { pointer: false } (the change happens with no cursor, e.g. a timer) choose how it's done. */
export const act = (name, o = {}) => ({ do: 'act', name, o });

export class Machine {
  constructor(def) { this.def = def; this.reset(); }
  reset() { this.s = { at: this.def.start, done: new Set(), vars: structuredClone(this.def.vars || {}) }; return this; }
  action(name) { return this.def.actions[name]; }
  can(name) {
    const a = this.action(name), s = this.s; if (!a) return false;
    const from = [].concat(a.from ?? []);
    return (!from.length || from.includes(s.at)) && !(a.once && s.done.has(name)) && (!a.if || !!a.if(s));
  }
  available() { return Object.keys(this.def.actions).filter((n) => this.can(n)); }
  view(at = this.s.at) { const v = this.def.views?.[at]; return v ? [].concat(v) : null; }
  /* apply an action: returns its steps (worked out from the state before it) and where it went */
  apply(name) {
    const a = this.action(name), from = this.s.at;
    const steps = typeof a.steps === 'function' ? a.steps(this.s) : a.steps || [];
    a.then?.(this.s); this.s.done.add(name); if (a.to) this.s.at = a.to;
    return { steps, from, to: this.s.at };
  }
}

/* a film script with act() steps → a plain engine script; warns when the film does something the machine wouldn't */
export function expand(script, def) {
  const m = new Machine(def), out = [], path = [];
  for (const st of script.steps || []) {
    if (st.do !== 'act') { out.push(st); continue; }
    const a = m.action(st.name);
    if (!a) { console.warn(`[playground] machine.js has no action "${st.name}"`); continue; }
    if (!m.can(st.name)) console.warn(`[playground] the film does "${st.name}" while the product is "${m.s.at}", which machine.js doesn't allow`);
    const { pointer = 'click', ...o } = st.o || {};
    if (pointer) out.push({ ...o, do: pointer, to: a.on });
    out.push(...m.apply(st.name).steps);
    path.push(st.name);
  }
  return { ...script, steps: out, path };
}

/* the visitor's session as a script: each action at the moment it was clicked, the camera following the views */
export function live(def, history, base = {}) {
  const m = new Machine(def), steps = [{ do: 'pause', dur: .05, at: 0 }];
  for (const h of history) {
    const r = m.apply(h.name);
    steps.push({ do: 'pause', dur: 0, at: h.at });                 // the clock jumps to the click
    const v0 = m.view(r.from), v1 = m.view(r.to);
    if (String(v0) !== String(v1)) steps.push(v1 ? zoom(v1[0], 'fit', { fill: v1[1] ?? .6, dur: 1.1 }) : unzoom({ dur: 1.1 }));
    steps.push(...r.steps);
  }
  return { script: { ...base, intro: 0, settle: 0, outro: 0, steps }, machine: m };
}

export const sel = (s) => s.replace(/@([\w-]+)/g, '[data-tour="$1"]');

// demo/playground: the tour plays once, then the product is the visitor's. One Tour on the engine's manual driver:
//   intro   the band, and a choice: Watch the tour, or Let me try
//   watch   script.js (its act() steps expanded through machine.js) plays, with pause, scrub and "Your turn"
//   turn    the product goes back to its start; a hotspot sits on every action machine.js allows right now, and a
//           click on one appends that action's steps to a live script the engine plays on from (playground.js)
// ?turn starts on the visitor's turn (&do=open,name applies actions first: handy for checking), ?t=12 freezes the
// film, ?record&ratio=16:9 is the clean stage for Monet Shot (the film, then a closing frame).
import { Tour, include } from '../tour/tour.js';
import film from './script.js';
import def from './machine.js';
import { Machine, expand, live, sel } from './playground.js';

const fmt = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const PLAY = '<svg viewBox="0 0 20 20"><path d="M6 3.8v12.4L16 10z"/></svg>', PAUSE = '<svg viewBox="0 0 20 20"><path d="M5.5 4h3v12h-3zM11.5 4h3v12h-3z"/></svg>';

export default function init(root) {
  const q = new URLSearchParams(location.search), rec = q.has('record');
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const stage = root.querySelector('[data-tour-stage]'), spotsEl = root.querySelector('.demo-playground-spots');
  const $ = (k) => [...root.querySelectorAll(`[data-pg="${k}"]`)];
  const F = expand(film, def);
  const filmScript = { ...F, outro: rec ? film.outro ?? 4 : .25 };
  const base = { size: film.size, enter: film.enter, pointer: film.pointer };
  const goals = Object.keys(def.actions).filter((n) => !def.actions[n].minor);
  let tour = null, phase = 'intro', hist = [], m = new Machine(def), busyUntil = 0, alive = true, swapT = 0, pingT = 0, refocus = false;
  const spots = new Map(), off = [];
  const on = (el, ev, fn, o) => { if (!el) return; el.addEventListener(ev, fn, o); off.push(() => el.removeEventListener(ev, fn, o)); };

  const setPhase = (p) => {
    phase = p;
    root.classList.toggle('is-watch', p === 'watch'); root.classList.toggle('is-turn', p === 'turn'); root.classList.toggle('is-begun', p !== 'intro');
    if (p !== 'turn') { spots.forEach((b) => b.remove()); spots.clear(); root.classList.remove('is-all'); }
  };

  // ── watching: the film, with its own little bar ──
  const watch = (from = 0) => {
    clearTimeout(swapT); root.classList.remove('is-swap');
    setPhase('watch'); tour.load(filmScript); tour.render(from, true); tour.play();
  };
  const syncPP = () => { const pp = $('pp')[0]; if (!pp) return; pp.innerHTML = tour?.playing ? PAUSE : PLAY; pp.setAttribute('aria-label', tour?.playing ? 'Pause' : 'Play'); };

  // ── the visitor's turn ──
  const toTurn = (instant) => {
    const go = () => {
      hist = []; m = new Machine(def); busyUntil = 0;
      tour.load(live(def, [], base).script); tour.render(0, true);
      setPhase('turn'); root.classList.remove('is-swap'); say(); place();
    };
    tour.pause(); clearTimeout(swapT);
    if (instant === true || reduce || phase === 'turn') return go();
    root.classList.add('is-swap'); swapT = setTimeout(go, 380);    // a short fade, so the reset never reads as a glitch
  };
  const act = (name, instant) => {
    if (phase !== 'turn' || !m.can(name)) return;
    const now = Math.max(tour.t, hist.length ? hist[hist.length - 1].at : 0);
    hist.push({ name, at: now });
    const L = live(def, hist, base); m = L.machine;
    tour.load(L.script);
    if (instant || reduce) { tour.render(tour.duration, true); busyUntil = 0; }
    else { tour.render(now, true); busyUntil = Math.min(tour.duration, now + 1.25); if (tour.duration - now > .03) tour.play(); }
    say(); place();
  };
  const next = () => {
    const avail = m.available(), fresh = (n) => avail.includes(n) && !m.s.done.has(n);
    return F.path.find(fresh) || avail.find((n) => fresh(n) && !def.actions[n].minor) || null;
  };
  const say = () => {
    const done = goals.filter((n) => m.s.done.has(n)).length, all = done === goals.length, n = next();
    $('count').forEach((e) => { e.textContent = `${done} / ${goals.length}`; });
    root.classList.toggle('is-all', all);
    const line = all ? "That's everything it does. Yours to keep, below." : n && hist.length ? `Next: ${def.actions[n].hint || n}.` : null;
    if (line) $('say').forEach((e) => { e.textContent = line; });
    else $('say').forEach((e) => { e.textContent = 'Click anything with a dot. It works the way you just watched.'; });
  };
  const target = (name) => tour.win.querySelector(sel(def.actions[name].on));
  const spot = (name) => {
    const a = def.actions[name], b = document.createElement('button');
    b.type = 'button'; b.className = 'demo-playground-spot' + (a.minor ? ' is-minor' : '');
    b.setAttribute('aria-label', a.hint || name);
    b.innerHTML = `<i></i><span class="demo-playground-tip" aria-hidden="true">${a.hint || name}</span>`;
    const hov = (k, v) => target(name)?.classList.toggle(k, v);
    b.addEventListener('pointerenter', () => hov('is-hover', true));
    b.addEventListener('pointerleave', () => { hov('is-hover', false); hov('is-press', false); });
    b.addEventListener('pointerdown', () => hov('is-press', true));
    b.addEventListener('click', () => { hov('is-hover', false); hov('is-press', false); refocus = document.activeElement === b && b.matches(':focus-visible'); act(name); });
    spotsEl.append(b); spots.set(name, b); return b;
  };
  // hotspots follow their targets every frame (the camera moves them), and show once the last action has settled
  function place() {
    if (phase !== 'turn' || !tour) return;
    const avail = new Set(m.available()), ready = !tour.playing || tour.t >= busyUntil, nx = next(), sr = stage.getBoundingClientRect();
    for (const [n, b] of spots) if (!avail.has(n)) { b.remove(); spots.delete(n); }
    for (const n of avail) {
      const el = target(n); if (!el) continue;
      const b = spots.get(n) || spot(n), r = el.getBoundingClientRect();
      const w = Math.max(r.width, 34), h = Math.max(r.height, 34);
      b.style.cssText = `left:${(r.left - sr.left + r.width / 2 - w / 2).toFixed(1)}px;top:${(r.top - sr.top + r.height / 2 - h / 2).toFixed(1)}px;width:${w.toFixed(1)}px;height:${h.toFixed(1)}px`;
      b.classList.toggle('is-shown', ready); b.classList.toggle('is-next', n === nx && ready); b.classList.toggle('is-below', r.top - sr.top < 64);
    }
    if (ready && refocus) { refocus = false; (spots.get(nx) || spots.values().next().value)?.focus({ preventScroll: true }); }
  }

  (async () => {
    await include(root);
    if (!alive) return;
    tour = new Tour(root, filmScript, { driver: 'manual' });
    if (rec || tour.fixT != null) return;              // the recording and frozen frames are the film alone
    tour.syncCtl = syncPP;
    const scrub = $('scrub')[0], time = $('time')[0];
    tour.onFrame = (t) => {
      if (phase === 'watch' && scrub) { scrub.max = tour.duration; if (document.activeElement !== scrub) scrub.value = t; scrub.parentNode.style.setProperty('--v', t / tour.duration); }
      if (phase === 'watch' && time) time.textContent = `${fmt(t)} / ${fmt(tour.duration)}`;
      if (phase === 'turn') place();
    };
    on(root, 'tour:end', () => { if (phase === 'watch') toTurn(); else place(); syncPP(); });
    $('watch').forEach((b) => on(b, 'click', () => watch(0)));
    $('try').forEach((b) => on(b, 'click', () => toTurn()));
    $('replay').forEach((b) => on(b, 'click', () => watch(1)));      // the band has already gone: start as it clears
    $('reset').forEach((b) => on(b, 'click', () => toTurn()));
    $('pp').forEach((b) => on(b, 'click', () => (tour.playing ? tour.pause() : tour.play())));
    on(scrub, 'input', () => { tour.pause(); tour.render(+scrub.value); });
    on(stage, 'pointerdown', (e) => {
      if (e.target.closest('button, a, input, .demo-playground-turn, .demo-playground-band, .tour-ctl')) return;
      if (phase === 'intro') { watch(0); return; }
      if (phase === 'turn') { spotsEl.classList.remove('is-ping'); void spotsEl.offsetWidth; spotsEl.classList.add('is-ping'); clearTimeout(pingT); pingT = setTimeout(() => spotsEl.classList.remove('is-ping'), 520); }
    });
    tour.render(0, true); syncPP();                     // reduced motion too: the band first, the choice is theirs
    window.playground = { watch, turn: toTurn, act, get state() { return m.s; }, get available() { return m.available(); } };
    if (q.has('turn')) { toTurn(true); (q.get('do') || '').split(',').filter(Boolean).forEach((n) => act(n.trim(), true)); }
  })();

  return () => { alive = false; clearTimeout(swapT); clearTimeout(pingT); off.forEach((f) => f()); spots.forEach((b) => b.remove()); tour?.destroy(); };
}

/* tour.js: a declarative product-tour engine. The shared foundation for every StyleFeatures demo film.
   Full reference: README.md beside this file. In short:

     import { Tour, click, type, show, zoom, chapter } from './tour.js';
     new Tour(rootElement, { size: [1200, 750], steps: [ chapter('01 / 03', 'Start <em>here</em>', 'One line.'),
                                                        click('@new'), show('@modal'), type('@name', 'Hello') ] });

   Everything on screen is a pure function of one number, t (seconds). Each frame the engine works out the
   product's state at t (classes, attributes, text, CSS variables, scroll positions), the camera, the fake
   cursor and the overlays, and writes only what changed. So any moment can be rendered on its own:
   ?t=12.5 freezes there, seek(t) jumps there, and a scroll, a clock or a screen recorder can all drive it.

   Selectors ('@name' is short for [data-tour="name"]) are measured against the product as it is at the moment
   each step happens, and measured again whenever the layout changes (fonts, resize, your CSS), so editing the
   product never breaks the script. */

const cl = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
export const ease = (t) => t * t * t * (t * (t * 6 - 15) + 10);           // smootherstep: settles, no overshoot
const lerp = (a, b, t) => a + (b - a) * t;
const rnd = (n) => { const x = Math.sin(n * 91.7 + 13.1) * 43758.5453; return x - Math.floor(x); };
const sel = (s) => (typeof s === 'string' ? s.replace(/@([\w-]+)/g, '[data-tour="$1"]') : s);
const fmtTime = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

/* ── step builders ─────────────────────────────────────────────────────────────────────────────
   Pointer steps run one after another on the script's clock. Side steps (zoom, show, hide, set, tween,
   chapter, caption) start at the current moment and let the next step start with them.
   Any step takes { at: seconds } to pin it, { wait: seconds } to start later, { parallel: true }
   so a pointer step doesn't hold up the next one, { block: true } so a side step does. */
export const move = (to, o = {}) => ({ ...o, do: 'move', to });
export const click = (to, o = {}) => ({ ...o, do: 'click', to });
export const dblclick = (to, o = {}) => ({ ...o, do: 'dblclick', to });
export const hover = (to, o = {}) => ({ ...o, do: 'hover', to });
export const type = (el, text, o = {}) => ({ ...o, do: 'type', el, text });
export const drag = (handle, o = {}) => ({ ...o, do: 'drag', handle });
export const scroll = (el, to, o = {}) => ({ ...o, do: 'scroll', el, to });
export const key = (keys, o = {}) => ({ ...o, do: 'key', keys: [].concat(keys) });
export const zoom = (to, z = 'fit', o = {}) => ({ ...o, do: 'zoom', to, z });
export const unzoom = (o = {}) => ({ ...o, do: 'zoom', to: null, z: 1 });
export const show = (el, o = {}) => ({ ...o, do: 'show', el });
export const hide = (el, o = {}) => ({ ...o, do: 'hide', el });
export const set = (el, changes, o = {}) => ({ ...o, do: 'set', el, changes });
export const tween = (el, prop, from, to, o = {}) => ({ ...o, do: 'tween', el, prop, from, to });
export const chapter = (n, title, line = '', o = {}) => ({ ...o, do: 'chapter', n, title, line });
export const caption = (text, o = {}) => ({ ...o, do: 'caption', text });
export const pause = (dur = 1) => ({ do: 'pause', dur });
export const stream = (el, o = {}) => ({ ...o, do: 'stream', el });   // reveal matches one after another, like output arriving
export const tap = click;                                                 // the same step; reads better in a touch film
export const longpress = (to, o = {}) => ({ ...o, do: 'longpress', to }); // press and hold; it fires after { hold } s
export const swipe = (on, o = {}) => ({ ...o, do: 'swipe', on });         // a finger flick: { by, scroll } or { prop, from, to } (README)
export const mark = (name, o = {}) => ({ ...o, do: 'mark', name });       // a named moment: tour.api.marks[name] is its time, and the list is in order (README)

/* eases for show / hide / tween: { ease: 'out' | 'ios' | 'spring' | (t) => t }. Default: smootherstep.
   'ios' is a critically damped spring (UIKit pushes and sheets), 'spring' overshoots by about 3%. */
export const eases = {
  linear: (t) => t,
  out: (t) => 1 - Math.pow(1 - t, 3),
  ios: (t) => (t >= 1 ? 1 : (1 - (1 + 9 * t) * Math.exp(-9 * t)) / (1 - 10 * Math.exp(-9))),
  spring: (t) => (t >= 1 ? 1 : 1 - Math.exp(-6 * t) * (Math.cos(5.3 * t) + 1.13 * Math.sin(5.3 * t))),
};
const easeOf = (e) => (typeof e === 'function' ? e : eases[e] || ease);

/* when each character of a typed string lands. rhythm: undefined (even, as before) | 'human' (beats between
   words, a reach for symbols, the odd hesitation) | 'stream' (chunks, like a model's reply arriving) */
function keyTimes(txt, cps, seed, rhythm, c) {
  const at = [], b = 1 / cps;
  if (rhythm === 'stream') {
