/* cta/install: the end of a launch page. The name, large, and the one way in: a command to copy, or a download. */
.cta-install{position:relative;min-height:100svh;display:grid;grid-template-rows:1fr auto;background:var(--page)}
.cta-install > *{width:100%}
.cta-install-in{display:grid;align-content:center;gap:clamp(28px,5vh,56px);padding-block:clamp(72px,12vh,140px) clamp(48px,8vh,96px)}
.cta-install-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,440px);gap:clamp(32px,6vw,96px);align-items:start}
.cta-install-row .sf-lede{padding-top:6px}
.cta-install-name h2{margin:0;padding-top:.08em;font:400 clamp(64px,14.5vw,236px)/.84 var(--serif);letter-spacing:-.03em;white-space:nowrap}
.cta-install-name em{font-style:italic}
.cta-install-card{position:relative;min-width:0;display:grid;grid-template-columns:minmax(0,1fr);gap:14px;padding:22px;background:var(--ph);box-shadow:0 0 0 1px var(--ph-line),0 30px 60px -40px rgba(25,24,22,.4)}
.cta-install-tabs{display:flex;gap:4px;border-bottom:1px solid var(--ph-line)}
.cta-install-tabs button{position:relative;padding:10px 12px 12px;border:0;background:none;font:500 13px/1 var(--sans);color:var(--ink-3);cursor:pointer}
.cta-install-tabs button[aria-selected=true]{color:var(--ink)}
.cta-install-tabs button[aria-selected=true]::after{content:"";position:absolute;left:12px;right:12px;bottom:-1px;height:2px;background:var(--ink)}
.cta-install-tabs button:focus-visible{outline:2px solid var(--note);outline-offset:-2px}
.cta-install-panel{display:flex;align-items:stretch;gap:8px;min-height:50px}
.cta-install-panel[hidden]{display:none}
.cta-install-cmd{flex:1;min-width:0;margin:0;display:flex;align-items:center;padding:0 14px;overflow-x:auto;background:var(--page);border-radius:var(--radius);font:500 13.5px/1.4 var(--mono);color:var(--ink);white-space:pre}
.cta-install-cmd::before{content:"$";margin-right:10px;color:var(--ink-3)}
.cta-install-copy{min-width:88px;justify-content:center}
.cta-install-panel.is-dl{flex-direction:column;align-items:flex-start;gap:14px}
.cta-install-panel.is-dl p{margin:0;color:var(--ink-2);font-size:14.5px;line-height:1.45}
.cta-install-small{margin:4px 0 0;font:400 12.5px/1.4 var(--sans);color:var(--ink-3)}
.cta-install-card .sf-note{justify-self:start}
.cta-install-said{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.cta-install-foot{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px 24px;padding-block:22px 28px;background:linear-gradient(var(--rule),var(--rule)) var(--gutter) 0/calc(100% - 2 * var(--gutter)) 1px no-repeat;font:400 12.5px/1.4 var(--sans);color:var(--ink-3)}
.cta-install-foot nav{display:flex;gap:20px}
.cta-install-foot a{text-decoration:none}.cta-install-foot a:hover{color:var(--ink)}
@media (max-width:860px){
  .cta-install-row{grid-template-columns:minmax(0,1fr)}
  .cta-install-name h2{font-size:clamp(52px,15.5vw,120px);white-space:normal}
  .cta-install-card{padding:16px}
  .cta-install-cmd{font-size:12.5px;padding:0 12px}
}

/* StyleFeatures scaffolds: the shared placeholder kit.
   Every scaffold section links this first. Tokens can be overridden per site in site.json "theme". */
:root{
  --page:#f5f3ef;--page-2:#ece9e3;--ph:#ffffff;--ph-line:#e3dfd7;--ph-mark:#d9d4ca;
  --ink:#191816;--ink-2:#5f5a53;--ink-3:#9c968c;--rule:#d8d3c9;
  --note:#c2643f;--note-bg:#fbf1ea;
  --serif:'Newsreader',Georgia,serif;--sans:'Inter Tight',system-ui,-apple-system,sans-serif;--mono:ui-monospace,'SF Mono',Menlo,monospace;
  --gutter:clamp(16px,3.4vw,48px);--max:1280px;--radius:2px;
  --ease:cubic-bezier(.2,.7,.2,1);
}
*{box-sizing:border-box}
html{background:var(--page);-webkit-text-size-adjust:100%}
body{margin:0;background:var(--page);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit}
img{display:block;max-width:100%}
.sf-wrap{max-width:var(--max);margin:0 auto;padding-inline:var(--gutter)}
.sf-sec{padding-block:clamp(72px,12vh,140px)}

/* ── type ───────────────────────────────────────────── */
.sf-eyebrow{margin:0 0 18px;font:500 12px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.sf-h1{margin:0;font:400 clamp(44px,6.4vw,96px)/.98 var(--serif);letter-spacing:-.025em}
.sf-h2{margin:0;font:400 clamp(32px,4vw,58px)/1.02 var(--serif);letter-spacing:-.02em}
.sf-h3{margin:0;font:500 clamp(19px,1.6vw,23px)/1.2 var(--sans);letter-spacing:-.01em}
.sf-lede{margin:0;max-width:34em;font:400 clamp(17px,1.4vw,20px)/1.5 var(--sans);color:var(--ink-2)}
.sf-small{font:400 13px/1.45 var(--sans);color:var(--ink-3)}

/* ── placeholder image: <figure class="ph" style="--r:4/5" data-ph="Image · 4:5" data-hint="What goes here"></figure> */
.ph{position:relative;margin:0;aspect-ratio:var(--r,4/3);background:var(--ph);border-radius:var(--radius);overflow:hidden;
  box-shadow:inset 0 0 0 1px var(--ph-line);min-width:0}
.ph::before{content:"";position:absolute;inset:0;pointer-events:none;
  background:
    linear-gradient(to top right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px)),
    linear-gradient(to bottom right,transparent calc(50% - .5px),var(--ph-mark) calc(50% - .5px),var(--ph-mark) calc(50% + .5px),transparent calc(50% + .5px));
  opacity:.55}
.ph::after{content:attr(data-ph) "\A" attr(data-hint);white-space:pre-line;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  width:max-content;max-width:min(80%,24em);padding:9px 13px;background:var(--ph);text-align:center;
  font:500 11px/1.45 var(--sans);letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);border-radius:var(--radius)}
.ph[data-hint]::after{font-size:11px}
.ph.is-bare::after{content:none}
.ph.is-round{border-radius:50%}
.ph.is-tone{--ph:var(--page-2)}              /* a placeholder on a white card */
.ph > *{position:relative;z-index:1}

/* video placeholder: add .ph-video; scaffold.js adds the transport */
.ph-video{--ph:#f7f6f3}
.ph-video::before{opacity:.35}
.ph-video::after{top:auto;bottom:44px;transform:translateX(-50%);max-width:min(86%,26em)}   /* label sits low, clear of the play button */
.ph-play{position:absolute;z-index:2;left:50%;top:50%;width:56px;height:56px;margin:-28px 0 0 -28px;border:0;border-radius:50%;
  background:var(--ink);color:var(--page);cursor:pointer;display:grid;place-items:center;transition:transform .4s var(--ease)}
.ph-play:hover{transform:scale(1.06)}
.ph-play[hidden],.ph-bar[hidden]{display:none}
.ph-play svg{width:20px;height:20px}
.ph-play:focus-visible{outline:2px solid var(--note);outline-offset:4px}
.ph-bar{position:absolute;z-index:2;left:16px;right:16px;bottom:14px;display:flex;align-items:center;gap:12px;font:500 11px/1 var(--mono);color:var(--ink-3)}
.ph-track{flex:1;height:2px;background:var(--ph-line);position:relative;overflow:hidden}
.ph-track i{position:absolute;inset:0;background:var(--ink);transform-origin:left;transform:scaleX(var(--p,0))}
.ph-video.is-playing::before{animation:ph-breathe 3.2s ease-in-out infinite}
@keyframes ph-breathe{50%{opacity:.12}}

/* placeholder copy: <p class="ph-text" style="--n:3"></p>  (n lines, last one short) */
.ph-text{--lh:1.6em;display:block;margin:0;height:calc(var(--n,3) * var(--lh));max-width:32em;
  background:repeating-linear-gradient(to bottom,var(--ph-line) 0 .55em,transparent .55em var(--lh));
  -webkit-mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat;
          mask:linear-gradient(#000,#000) top/100% calc(100% - var(--lh)) no-repeat,linear-gradient(90deg,#000 var(--last,58%),transparent 0) bottom/100% var(--lh) no-repeat}
.ph-logo{display:inline-flex;align-items:center;justify-content:center;height:34px;min-width:110px;padding:0 14px;border-radius:var(--radius);
  box-shadow:inset 0 0 0 1px var(--ph-line);background:var(--ph);font:600 11px/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}

/* ── controls ───────────────────────────────────────── */
.sf-btn{display:inline-flex;align-items:center;gap:10px;padding:14px 22px;border:0;border-radius:var(--radius);background:var(--ink);color:var(--page);
  font:500 14px/1 var(--sans);text-decoration:none;cursor:pointer;transition:background-color .3s ease,color .3s ease,box-shadow .3s ease}
.sf-btn:hover{background:#000}
.sf-btn--ghost{background:transparent;color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)}
.sf-btn--ghost:hover{background:var(--ink);color:var(--page)}
.sf-btn--text{padding:6px 0;background:none;color:var(--ink);box-shadow:inset 0 -1px 0 currentColor}
.sf-btn--text:hover{background:none;color:var(--ink-2)}
.sf-btn:focus-visible,.sf-field:focus-visible{outline:2px solid var(--note);outline-offset:3px}
.sf-field{width:100%;padding:14px 0;border:0;border-bottom:1px solid var(--rule);background:transparent;font:400 16px/1.2 var(--sans);color:var(--ink);border-radius:0}
.sf-field::placeholder{color:var(--ink-3)}
.sf-rule{height:0;border:0;border-top:1px solid var(--rule);margin:0}

/* ── notes: what goes here / who it suits. <span class="sf-note">Swap for your logo</span>; html.sf-clean hides them */
.sf-note{display:inline-flex;align-items:center;gap:7px;padding:5px 9px 5px 7px;border-radius:var(--radius);background:var(--note-bg);color:var(--note);
  font:500 11px/1.25 var(--sans);letter-spacing:.01em;vertical-align:middle;white-space:normal;max-width:30em}
.sf-note::before{content:"";flex:none;width:6px;height:6px;border-radius:50%;background:currentColor}
.sf-note.is-pin{position:absolute;z-index:5}
html.sf-clean .sf-note{display:none!important}

/* ── reveal ─────────────────────────────────────────── */
[data-reveal]{opacity:0;transform:translateY(14px);transition:opacity 1s var(--ease),transform 1.2s var(--ease);transition-delay:calc(var(--i,0) * 80ms)}
[data-reveal].is-in{opacity:1;transform:none}
.no-js [data-reveal]{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-reveal]{opacity:1;transform:none;transition:none}}

/* ── preview spec card (only on preview pages) ───────── */
.sf-spec{position:fixed;z-index:9999;left:14px;bottom:14px;max-width:min(360px,calc(100vw - 28px));padding:14px 16px;border-radius:4px;
  background:rgba(255,255,255,.94);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);box-shadow:0 0 0 1px var(--ph-line),0 10px 30px -14px rgba(0,0,0,.3);
  font:400 12px/1.45 var(--sans);color:var(--ink-2)}
.sf-spec b{display:block;font:500 14px/1.25 var(--sans);color:var(--ink);margin:6px 0 3px}
.sf-spec .sf-kind{margin-right:6px}
.sf-spec ul{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-wrap:wrap;gap:5px}
.sf-spec li{padding:3px 7px;border-radius:2px;background:var(--page);color:var(--ink-2);font-size:11px}
.sf-spec button{margin-top:10px;padding:0;border:0;background:none;font:500 11px/1 var(--sans);color:var(--ink-3);text-decoration:underline;cursor:pointer}
.sf-spec.is-min p,.sf-spec.is-min ul{display:none}
.sf-thumb .sf-spec{display:none}
@media (max-width:700px){.sf-spec{left:8px;bottom:8px;padding:10px 12px}}
.sf-kind{display:inline-flex;align-items:center;gap:6px;padding:4px 8px 4px 7px;border-radius:2px;font:600 10px/1 var(--sans);letter-spacing:.12em;text-transform:uppercase}
.sf-kind::before{content:"";width:7px;height:7px;border-radius:50%;background:currentColor}
.sf-kind--static{background:#eceae5;color:#6f6a62}
.sf-kind--interactive{background:#fbeee6;color:#b65a35}
.sf-kind--video{background:#1d1c1a;color:#f2efe9}

/* demo/playground: the placeholder product the tour plays and the visitor then drives, in design pixels (1200 × 750).
   Replace this file with your product's own CSS when your screens go in (AGENT.md, step 2). Scoped to .demo-playground-app
   so it never meets another format's product on the same page. */
.demo-playground-app{--insp:0;position:relative;display:grid;grid-template-columns:212px minmax(0,1fr) calc(var(--insp) * 300px);background:var(--ph);
  font:400 13px/1.35 var(--sans);color:var(--ink);text-align:left;overflow:hidden;--line:var(--ph-line);--soft:var(--page)}
.demo-playground-app svg{width:16px;height:16px;flex:none;fill:none;stroke:currentColor;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
.demo-playground-app button{font:inherit;border:0;background:none;color:inherit;padding:0}
.demo-playground-app [data-tone="1"]{--tone:var(--ph)}.demo-playground-app [data-tone="2"]{--tone:var(--page-2)}.demo-playground-app [data-tone="3"]{--tone:var(--ink-2)}
.demo-playground-app [data-tone="4"]{--tone:var(--rule)}.demo-playground-app [data-tone="5"]{--tone:var(--ink)}

/* sidebar */
.demo-playground-app .app-side{display:flex;flex-direction:column;gap:6px;padding:16px 12px 14px;background:var(--soft);border-right:1px solid var(--line);min-width:0}
.demo-playground-app .app-ws{display:flex;align-items:center;gap:9px;padding:4px 8px 14px;font-weight:600}
.demo-playground-app .app-ws svg{margin-left:auto;color:var(--ink-3)}
.demo-playground-app .app-logo{width:22px;height:22px;border-radius:6px;background:var(--ink)}
.demo-playground-app .app-nav{display:grid;gap:2px}
.demo-playground-app .app-nav a{display:flex;align-items:center;gap:10px;padding:7px 8px;border-radius:6px;color:var(--ink-2);font-weight:500}
.demo-playground-app .app-nav a svg{color:var(--ink-3)}
.demo-playground-app .app-nav a.is-on{background:var(--ph);color:var(--ink);box-shadow:0 0 0 1px var(--line)}
.demo-playground-app .app-nav a.is-on svg{color:var(--ink)}
.demo-playground-app .app-label{margin:18px 8px 4px;font:500 11px/1 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3)}
.demo-playground-app .app-recent{display:grid;gap:2px}
.demo-playground-app .app-recent > span{display:flex;align-items:center;gap:10px;padding:7px 8px;color:var(--ink-2)}
.demo-playground-app .app-recent i{width:10px;height:10px;border-radius:3px;background:var(--line)}
.demo-playground-app .app-recent b{height:7px;width:var(--w);border-radius:4px;background:var(--line)}
.demo-playground-app .app-recent-new{--in:0;opacity:var(--in);margin-bottom:calc((var(--in) - 1) * 33px);font-weight:500;color:var(--ink)!important}
.demo-playground-app .app-recent-new i{background:var(--tone,var(--ink))!important;box-shadow:inset 0 0 0 1px var(--line)}
.demo-playground-app .app-me{margin-top:auto;display:flex;align-items:center;gap:10px;padding:10px 8px 0;border-top:1px solid var(--line)}
.demo-playground-app .app-me .ph{width:30px;flex:none}
.demo-playground-app .app-me b{display:block;font-weight:500}.demo-playground-app .app-me small{color:var(--ink-3);font-size:12px}

/* toolbar */
.demo-playground-app .app-main{position:relative;display:flex;flex-direction:column;min-width:0}
.demo-playground-app .app-bar{flex:none;height:60px;display:flex;align-items:center;gap:10px;padding:0 20px 0 26px;border-bottom:1px solid var(--line)}
.demo-playground-app .app-bar h4{margin:0 auto 0 0;display:flex;align-items:center;gap:9px;font:600 17px/1 var(--sans);letter-spacing:-.01em}
.demo-playground-app .app-count{min-width:22px;padding:4px 7px;border-radius:99px;background:var(--soft);box-shadow:inset 0 0 0 1px var(--line);font:500 11.5px/1 var(--sans);color:var(--ink-2);text-align:center}
.demo-playground-app .app-search{display:flex;align-items:center;gap:8px;width:200px;height:32px;padding:0 10px;border-radius:7px;box-shadow:inset 0 0 0 1px var(--line);color:var(--ink-3)}
.demo-playground-app .app-seg{display:flex;padding:3px;border-radius:8px;background:var(--soft);box-shadow:inset 0 0 0 1px var(--line);font-weight:500;color:var(--ink-3)}
.demo-playground-app .app-seg span{padding:6px 11px;border-radius:5px}
.demo-playground-app .app-seg .is-on{background:var(--ph);color:var(--ink);box-shadow:0 1px 2px rgba(25,24,22,.1),0 0 0 1px var(--line)}
.demo-playground-app .app-btn{display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 13px;border-radius:7px;background:var(--ph);box-shadow:inset 0 0 0 1px var(--rule);font-weight:500;color:var(--ink);white-space:nowrap}
.demo-playground-app .app-btn.is-primary{background:var(--ink);color:var(--page);box-shadow:none}
.demo-playground-app .app-btn.is-hover{background:var(--soft)}
.demo-playground-app .app-btn.is-primary.is-hover{background:#000}
.demo-playground-app .is-press{transform:scale(.96)}

/* body: an empty state that fills in */
.demo-playground-app .app-body{position:relative;flex:1;min-height:0;padding:24px 26px}
.demo-playground-app .app-empty{--in:1;position:absolute;inset:24px 26px;display:grid;place-content:center;justify-items:center;gap:8px;border-radius:12px;border:1.5px dashed var(--rule);text-align:center;opacity:var(--in);transform:scale(calc(.98 + .02 * var(--in)))}
.demo-playground-app .app-empty-art{position:relative;width:96px;height:72px;margin-bottom:12px}
.demo-playground-app .app-empty-art .ph{position:absolute;width:56px;border-radius:8px}
.demo-playground-app .app-empty-art .ph:first-child{left:0;top:4px;transform:rotate(-6deg)}
.demo-playground-app .app-empty-art .ph:last-child{right:0;top:10px;transform:rotate(5deg);box-shadow:inset 0 0 0 1px var(--line),0 8px 18px -10px rgba(25,24,22,.35)}
.demo-playground-app .app-empty b{font:600 16px/1.2 var(--sans)}
.demo-playground-app .app-empty p{margin:0;color:var(--ink-3)}
.demo-playground-app .app-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px 20px}
.demo-playground-app .app-card{--in:0;position:relative;display:grid;gap:7px;padding:8px 8px 12px;border-radius:12px;opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 14px))}
.demo-playground-app .app-card .app-cover{border-radius:8px;background:var(--tone,var(--ph))}
.demo-playground-app .app-card b{padding:2px 4px 0;font-weight:600}
.demo-playground-app .app-card small{padding:0 4px;color:var(--ink-3);font-size:12px}
.demo-playground-app .app-card > i{height:8px;width:var(--w);margin:6px 4px 2px;border-radius:4px;background:var(--rule)}
.demo-playground-app .app-bars{display:flex;gap:6px}.demo-playground-app .app-bars i{height:6px;width:56px;border-radius:3px;background:var(--line)}.demo-playground-app .app-bars i+i{width:34px}
.demo-playground-app .app-card.is-hover{background:var(--soft)}
.demo-playground-app .app-card.is-sel{background:var(--soft);box-shadow:0 0 0 1.5px var(--ink)}
.demo-playground-app .app-badge{position:absolute;right:16px;top:16px;padding:4px 7px;border-radius:5px;background:var(--ink);color:var(--page);font:600 10.5px/1 var(--sans);font-style:normal;letter-spacing:.04em;text-transform:uppercase}

/* the room: a project opened full size, growing out of the first card */
.demo-playground-app .app-room{--open:0;position:absolute;inset:0;z-index:3;display:flex;flex-direction:column;background:var(--ph);
  clip-path:inset(calc((1 - var(--open)) * 24px) calc((1 - var(--open)) * (100% - 26px - (100% - 92px) / 3)) calc((1 - var(--open)) * (100% - 278px)) calc((1 - var(--open)) * 26px) round calc(12px - var(--open) * 12px));
  opacity:min(1,calc(var(--open) * 6));pointer-events:none}
.demo-playground-app .app-room-bar{flex:none;display:flex;align-items:center;gap:10px;height:54px;padding:0 26px;border-bottom:1px solid var(--line);opacity:calc(var(--open) * 2 - 1)}
.demo-playground-app .app-room-bar b{font:600 15px/1 var(--sans)}
.demo-playground-app .app-tabs{margin-left:auto;display:flex;gap:4px;color:var(--ink-3);font-weight:500}
.demo-playground-app .app-tabs span{padding:7px 11px;border-radius:6px}.demo-playground-app .app-tabs .is-on{color:var(--ink);background:var(--soft)}
.demo-playground-app .app-room-scroll{flex:1;min-height:0;overflow:hidden;padding:22px 26px 40px}
.demo-playground-app .app-room-scroll > * + *{margin-top:24px}
.demo-playground-app .app-room-hero{transform:scale(calc(.94 + .06 * var(--open)));transform-origin:0 0}
.demo-playground-app .app-room-cols{display:grid;grid-template-columns:1fr 1.15fr;gap:28px}
.demo-playground-app .app-h{margin:0 0 10px;font:500 11px/1 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3)}
.demo-playground-app .app-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.demo-playground-app .app-stats > span{position:relative;display:grid;gap:8px;align-content:start;padding:14px;border-radius:10px;box-shadow:inset 0 0 0 1px var(--line);height:150px}
.demo-playground-app .app-stats small{color:var(--ink-3);font-size:12px}
.demo-playground-app .app-stats b{height:14px;width:60%;border-radius:4px;background:var(--rule)}
.demo-playground-app .app-stats i{position:absolute;left:14px;right:14px;bottom:14px;height:calc(var(--h) * 70px);border-radius:4px;background:var(--page-2)}
.demo-playground-app .app-stats > span.is-hover{box-shadow:inset 0 0 0 1.5px var(--ink)}
.demo-playground-app .app-stats > span.is-hover i{background:var(--ink-2)}
.demo-playground-app .app-tip{--in:0;position:absolute;left:50%;bottom:calc(100% + 8px);padding:7px 10px;border-radius:6px;background:var(--ink);color:var(--page);font:500 12px/1 var(--sans);font-style:normal;white-space:nowrap;opacity:var(--in);transform:translate(-50%,calc((1 - var(--in)) * 6px))}
.demo-playground-app .app-room-row{display:grid;grid-template-columns:1fr 1fr 1.1fr;gap:16px;align-items:start}

/* inspector: opens beside the work */
.demo-playground-app .app-insp{position:relative;overflow:hidden;border-left:1px solid var(--line);background:var(--ph)}
.demo-playground-app .app-insp-in{position:absolute;top:0;bottom:0;left:0;width:300px;padding:18px 20px;display:grid;align-content:start;gap:12px;transform:translateX(calc((1 - var(--insp)) * 40px));opacity:var(--insp)}
.demo-playground-app .app-insp-head{display:flex;align-items:center;justify-content:space-between;font:600 15px/1 var(--sans)}
.demo-playground-app .app-x{display:grid;place-items:center;width:26px;height:26px;border-radius:6px;color:var(--ink-3)}
.demo-playground-app .app-x.is-hover{background:var(--soft);color:var(--ink)}
.demo-playground-app .app-insp .app-cover{border-radius:8px;background:var(--tone,var(--ph))}
.demo-playground-app .app-insp .app-h{margin:8px 0 0}
.demo-playground-app .app-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid var(--line);color:var(--ink-2);font-weight:500}
.demo-playground-app .app-row.is-col{flex-direction:column;align-items:stretch;gap:12px}
.demo-playground-app .app-row.is-col > span:first-child{display:flex;justify-content:space-between}
.demo-playground-app .app-row b{font-weight:500;color:var(--ink);font-variant-numeric:tabular-nums}
.demo-playground-app .app-switch{--on:0;position:relative;width:36px;height:21px;border-radius:99px;background:color-mix(in srgb,var(--ink) calc(var(--on) * 100%),var(--rule))}
.demo-playground-app .app-switch i{position:absolute;top:2.5px;left:2.5px;width:16px;height:16px;border-radius:50%;background:var(--ph);box-shadow:0 1px 3px rgba(25,24,22,.3);transform:translateX(calc(var(--on) * 15px))}
.demo-playground-app .app-slider{--v:.3;position:relative;height:18px;margin:0 8px}
.demo-playground-app .app-slider::before,.demo-playground-app .app-slider i{content:"";position:absolute;left:0;right:0;top:7px;height:4px;border-radius:2px;background:var(--line)}
.demo-playground-app .app-slider i{right:auto;width:calc(var(--v) * 100%);background:var(--ink)}
.demo-playground-app .app-slider b{position:absolute;top:0;left:calc(var(--v) * 100%);width:18px;height:18px;margin-left:-9px;border-radius:50%;background:var(--ph);box-shadow:0 0 0 1px var(--rule),0 2px 5px rgba(25,24,22,.25)}
.demo-playground-app .app-slider b.is-press{transform:scale(1.15)}
.demo-playground-app .app-tones{display:flex;gap:10px}
.demo-playground-app .app-tones i{width:30px;height:30px;border-radius:8px;background:var(--tone);box-shadow:inset 0 0 0 1px var(--rule)}
.demo-playground-app .app-tones i.is-on{outline:2px solid var(--ink);outline-offset:2px}

/* modal */
.demo-playground-app .app-scrim{--in:0;position:absolute;inset:0;z-index:5;background:rgba(25,24,22,.22);opacity:var(--in);pointer-events:none}
.demo-playground-app .app-modal{--in:0;position:absolute;z-index:6;left:50%;top:50%;width:440px;margin:-190px 0 0 -220px;padding:22px 22px 18px;display:grid;gap:12px;border-radius:14px;background:var(--ph);
  box-shadow:0 0 0 1px var(--line),0 30px 60px -24px rgba(25,24,22,.5);opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 14px)) scale(calc(.97 + .03 * var(--in)));pointer-events:none}
.demo-playground-app .app-modal-t{font:600 17px/1.2 var(--sans)}
.demo-playground-app .app-field{display:grid;gap:7px;padding:10px 12px;border-radius:8px;box-shadow:inset 0 0 0 1px var(--rule)}
.demo-playground-app .app-field small{color:var(--ink-3);font-size:12px}
.demo-playground-app .app-field span{min-height:20px;font:500 15px/20px var(--sans)}
.demo-playground-app .app-field span:empty::before{content:attr(data-placeholder);color:var(--ink-3)}
.demo-playground-app .app-field span.is-caret::after{content:"";display:inline-block;width:1.5px;height:17px;margin-left:1px;vertical-align:-3px;background:var(--ink)}
.demo-playground-app .app-field span:empty.is-caret::before{content:none}
.demo-playground-app .app-field:has(.is-caret),.demo-playground-app .app-field.is-hover{box-shadow:inset 0 0 0 1.5px var(--ink)}
.demo-playground-app .app-modal .app-h{margin:6px 0 0}
.demo-playground-app .app-tpls{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.demo-playground-app .app-tpl{display:grid;gap:7px;padding:7px 7px 9px;border-radius:9px;box-shadow:inset 0 0 0 1px var(--line);font-weight:500;color:var(--ink-2)}
.demo-playground-app .app-tpl .ph{border-radius:5px}
.demo-playground-app .app-tpl.is-hover{background:var(--soft)}
.demo-playground-app .app-tpl.is-on{box-shadow:inset 0 0 0 1.5px var(--ink);color:var(--ink)}
.demo-playground-app .app-modal-foot{display:flex;justify-content:flex-end;gap:8px;margin-top:6px}

/* share popover and toast */
.demo-playground-app .app-pop{--in:0;position:absolute;z-index:6;right:96px;top:98px;width:380px;padding:16px;display:grid;gap:14px;border-radius:12px;background:var(--ph);
  box-shadow:0 0 0 1px var(--line),0 24px 50px -22px rgba(25,24,22,.5);opacity:var(--in);transform:translateY(calc((1 - var(--in)) * -8px));pointer-events:none}
.demo-playground-app .app-pop > b{font:600 15px/1 var(--sans)}
.demo-playground-app .app-link{display:flex;align-items:center;gap:8px;padding:4px 4px 4px 12px;border-radius:8px;box-shadow:inset 0 0 0 1px var(--rule)}
.demo-playground-app .app-link span{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;color:var(--ink-2)}
.demo-playground-app .app-people{display:flex;align-items:center;gap:0}
.demo-playground-app .app-people .ph{width:28px;margin-right:-7px;box-shadow:0 0 0 2px var(--ph)}
.demo-playground-app .app-people small{margin-left:18px;color:var(--ink-3);font-size:12.5px}
.demo-playground-app .app-toast{--in:0;position:absolute;z-index:7;left:50%;bottom:24px;display:flex;align-items:center;gap:9px;padding:11px 16px 11px 13px;border-radius:10px;background:var(--ink);color:var(--page);font-weight:500;
  box-shadow:0 16px 34px -16px rgba(25,24,22,.6);opacity:var(--in);transform:translate(-50%,calc((1 - var(--in)) * 14px))}
.demo-playground-app .app-toast svg{color:var(--page)}

.demo-playground-app .app-people .app-done{margin-left:auto}
.demo-playground-app .app-tones i.is-hover{box-shadow:inset 0 0 0 1px var(--ink-3)}
.demo-playground-app .app-switch.is-hover{filter:brightness(.96)}

@import url("../tour/tour.css");
@import url("product.css");
/* demo/playground: the tour plays once, then the visitor drives the same product. tour.css (the shared engine
   look) and product.css (the placeholder product) are imported above. --demo-playground-spot colours the hotspots. */

.demo-playground{--demo-playground-spot:var(--note);background:var(--page)}
.demo-playground > [data-tour-stage]{height:100svh;min-height:560px}

/* ── opening band and closing frame (stage coordinates) ── */
.demo-playground-band,.demo-playground-end{position:absolute;z-index:10;left:0;right:0;bottom:0;display:flex;align-items:flex-end;justify-content:space-between;gap:clamp(24px,4vw,64px);
  padding:clamp(22px,3.6vh,40px) var(--gutter) clamp(26px,4.6vh,50px);background:var(--page)}
.demo-playground-band h1,.demo-playground-end h2{margin:0;padding-top:.08em;font:400 clamp(56px,9.4vw,172px)/.86 var(--serif);letter-spacing:-.028em;white-space:nowrap;color:var(--ink)}
.demo-playground-band em,.demo-playground-end em,.demo-playground-turn em{font-style:italic}
.demo-playground-band .sf-eyebrow,.demo-playground-end .sf-eyebrow{margin-bottom:14px}
.demo-playground-side{max-width:26em;display:grid;gap:18px;justify-items:start}
.demo-playground-lede{margin:0;font:400 clamp(16px,1.35vw,19px)/1.45 var(--sans);color:var(--ink-2)}
.demo-playground-act{display:flex;flex-wrap:wrap;align-items:center;gap:10px 16px}
.demo-playground-act svg{margin-right:2px}
.demo-playground-band .sf-note{max-width:30em}
.demo-playground-url{font:500 13px/1 var(--mono);color:var(--ink-3)}
.demo-playground-end{opacity:var(--in,0);transform:translateY(calc((1 - var(--in,0)) * 40px))}
@media (max-aspect-ratio:23/20){
  .demo-playground-band,.demo-playground-end{flex-direction:column;align-items:flex-start;gap:16px}
  .demo-playground-band h1,.demo-playground-end h2{font-size:clamp(50px,15vw,96px)}
  .demo-playground-band .sf-note{display:none}
}

/* ── while the tour plays: the engine's control bar, plus a way out ── */
.demo-playground-ctl{transition:opacity .4s ease}
.demo-playground:not(.is-watch) .demo-playground-ctl{opacity:0;pointer-events:none}
.demo-playground-ctl .tour-pp:empty{display:none}
.demo-playground-skip{flex:none;display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 4px 0 12px;border:0;border-left:1px solid var(--ph-line);background:none;
  font:500 12.5px/1 var(--sans);color:var(--ink);cursor:pointer}
.demo-playground-skip svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;transition:transform .35s var(--ease)}
.demo-playground-skip:hover svg{transform:translateX(3px)}
.demo-playground-skip:focus-visible{outline:2px solid var(--note);outline-offset:2px}
.demo-playground.is-watch:not(.is-stack) .tour-card{bottom:calc(var(--gutter,32px) + 52px)}

/* ── your turn: a card beside the product, and a hotspot on everything clickable ── */
.demo-playground-turn{position:absolute;z-index:6;left:var(--gutter,32px);bottom:var(--gutter,32px);width:min(calc(var(--su) * 46),calc(100% - 2 * var(--gutter,32px)));
  padding:calc(var(--su)*1.8) calc(var(--su)*2.1) calc(var(--su)*1.9);background:var(--ph);box-shadow:0 0 0 1px var(--ph-line),0 20px 44px -24px rgba(25,24,22,.45);
  opacity:0;visibility:hidden;transform:translateY(10px);transition:opacity .5s var(--ease),transform .6s var(--ease),visibility 0s linear .5s}
.demo-playground.is-turn .demo-playground-turn{opacity:1;visibility:visible;transform:none;transition:opacity .5s var(--ease) .15s,transform .6s var(--ease) .15s}
.is-stack .demo-playground-turn{left:4%;right:4%;width:auto;bottom:auto;top:var(--card-top)}
.demo-playground-turn-n{display:flex;justify-content:space-between;gap:12px;margin:0;font:500 max(10.5px,calc(var(--su)*1.15))/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.demo-playground-turn-n span + span{letter-spacing:.06em;text-transform:none;font-variant-numeric:tabular-nums}
.demo-playground-turn h3{margin:calc(var(--su)*1) 0 calc(var(--su)*.75);font:400 max(25px,calc(var(--su)*3.7))/1 var(--serif);letter-spacing:-.018em;color:var(--ink)}
.demo-playground-turn-line{margin:0;min-height:2.9em;font:400 max(13.5px,calc(var(--su)*1.6))/1.45 var(--sans);color:var(--ink-2)}
.demo-playground-turn-act{display:flex;flex-wrap:wrap;align-items:center;gap:10px 18px;margin-top:calc(var(--su)*1.6)}
.demo-playground-turn-act .sf-btn:not(.sf-btn--text){padding:11px 16px}
.demo-playground-turn-act svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.demo-playground-get{margin-left:auto}
.demo-playground.is-all .demo-playground-get{box-shadow:inset 0 -2px 0 var(--demo-playground-spot)}

.demo-playground-spots{position:absolute;inset:0;z-index:5;pointer-events:none}
.demo-playground-spot{position:absolute;margin:0;padding:0;border:0;border-radius:8px;background:transparent;cursor:pointer;pointer-events:auto;
  opacity:0;transition:opacity .35s var(--ease),box-shadow .25s ease}
.demo-playground-spot.is-shown{opacity:1}
.demo-playground-spot:not(.is-shown){pointer-events:none}
.demo-playground-spot:hover{box-shadow:0 0 0 2px color-mix(in srgb,var(--demo-playground-spot) 55%,transparent)}
.demo-playground-spot:focus-visible{outline:2px solid var(--demo-playground-spot);outline-offset:3px}
.demo-playground-spot > i{position:absolute;right:-6px;top:-6px;width:12px;height:12px;border-radius:50%;background:var(--demo-playground-spot);box-shadow:0 0 0 2px var(--ph),0 2px 6px rgba(25,24,22,.25)}
.demo-playground-spot > i::after{content:"";position:absolute;inset:0;border-radius:50%;background:var(--demo-playground-spot);animation:demo-playground-pulse 1.9s cubic-bezier(.2,.7,.2,1) infinite}
.demo-playground-spot.is-minor > i{width:8px;height:8px;right:-4px;top:-4px;background:var(--ink-3)}
.demo-playground-spot.is-minor > i::after{animation:none;opacity:0}
.demo-playground-spots.is-ping .demo-playground-spot > i{animation:demo-playground-ping .5s var(--ease)}
@keyframes demo-playground-pulse{0%{transform:scale(1);opacity:.55}80%,100%{transform:scale(3.1);opacity:0}}
@keyframes demo-playground-ping{50%{transform:scale(1.7)}}
.demo-playground-tip{position:absolute;left:50%;bottom:calc(100% + 12px);transform:translate(-50%,4px);width:max-content;max-width:220px;padding:7px 10px;border-radius:6px;
  background:var(--ink);color:var(--page);font:500 12px/1.2 var(--sans);opacity:0;pointer-events:none;transition:opacity .3s,transform .4s var(--ease)}
.demo-playground-tip::after{content:"";position:absolute;left:50%;top:100%;margin-left:-5px;border:5px solid transparent;border-top-color:var(--ink)}
.demo-playground-spot.is-below .demo-playground-tip{bottom:auto;top:calc(100% + 12px)}
.demo-playground-spot.is-below .demo-playground-tip::after{top:auto;bottom:100%;border-top-color:transparent;border-bottom-color:var(--ink)}
.demo-playground-spot.is-next .demo-playground-tip,.demo-playground-spot:hover .demo-playground-tip,.demo-playground-spot:focus-visible .demo-playground-tip{opacity:1;transform:translate(-50%,0)}
.demo-playground .tour-rig{transition:opacity .35s var(--ease)}
.demo-playground.is-swap .tour-rig{opacity:0}
.demo-playground.is-turn .demo-playground-win{cursor:default}
.demo-playground-win .tour-chrome{background:var(--page)}

@media (prefers-reduced-motion:reduce){
  .demo-playground-spot > i::after{animation:none;transform:scale(2);opacity:.18}
  .demo-playground-turn,.demo-playground.is-turn .demo-playground-turn,.demo-playground .tour-rig,.demo-playground-tip{transition:none}
}

/* ── ?record: sizes follow the stage, the address replaces the buttons ── */
.demo-playground.is-record .demo-playground-band,.demo-playground.is-record .demo-playground-end{padding:calc(var(--su)*4) calc(var(--su)*5.5) calc(var(--su)*5)}
.demo-playground.is-record.is-stack .demo-playground-band,.demo-playground.is-record.is-stack .demo-playground-end{flex-direction:column;align-items:flex-start;gap:calc(var(--su)*2.4)}
.demo-playground.is-record .demo-playground-band h1,.demo-playground.is-record .demo-playground-end h2{font-size:calc(var(--su)*15)}
.demo-playground.is-record.is-stack .demo-playground-band h1,.demo-playground.is-record.is-stack .demo-playground-end h2{font-size:calc(var(--su)*13.5)}
.demo-playground.is-record .demo-playground-lede{font-size:calc(var(--su)*2.1)}
.demo-playground.is-record .sf-eyebrow{font-size:calc(var(--su)*1.3)}
.demo-playground.is-record .demo-playground-side{max-width:calc(var(--su)*52)}
.demo-playground.is-record .demo-playground-act{display:none}
.demo-playground.is-record .demo-playground-url{font-size:calc(var(--su)*2.2);color:var(--ink)}

/* tour.css: the engine's own look. Window chromes, the cursor, ripples, chapter card, caption, key caps,
   the play controls, the auto-play switch and the ?record stage. Shared by every demo film; a template
   restyles it through these tokens rather than editing it:
     --tour-stage  backdrop behind the window        --tour-win-radius  window corners (design px)
     --tour-ring   click ripple colour               --tour-cap-bg / --tour-cap-ink  caption pill
   Sizes on the stage scale with --su (a hundredth of the stage's short side, set by tour.js). */

[data-tour-root]{position:relative;--tour-stage:var(--page-2,#ece9e3);--tour-ring:rgba(25,24,22,.42);--tour-cap-bg:var(--ink,#191816);--tour-cap-ink:var(--page,#f5f3ef);--tour-win-radius:12px}
[data-tour-stage]{position:sticky;top:0;height:100svh;overflow:hidden;background:var(--tour-stage);isolation:isolate;--su:9px}
[data-tour-root].is-play [data-tour-stage],[data-tour-root].is-still [data-tour-stage]{position:relative}
.tour-rig{position:absolute;inset:0}

/* the window: design pixels, scaled by the camera */
[data-tour-window]{position:absolute;left:0;top:0;transform-origin:0 0;display:flex;flex-direction:column;overflow:hidden;
  border-radius:var(--tour-win-radius);background:var(--ph,#fff);
  box-shadow:0 0 0 1px rgba(25,24,22,.12),0 40px 90px -40px rgba(25,24,22,.5),0 12px 28px -16px rgba(25,24,22,.28)}
[data-tour-window] > :not(.tour-chrome){flex:1;min-height:0}
.tour-chrome{flex:none;height:40px;display:flex;align-items:center;gap:14px;padding:0 14px;background:var(--page,#f5f3ef);border-bottom:1px solid var(--ph-line,#e3dfd7);font:500 12.5px/1 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-lights{display:flex;gap:8px}
.tour-lights i{width:12px;height:12px;border-radius:50%;background:#ec6a5e;box-shadow:inset 0 0 0 .5px rgba(0,0,0,.12)}
.tour-lights i+i{background:#f4bf4f}.tour-lights i+i+i{background:#61c554}
.tour-navs{display:flex;gap:10px}.tour-navs.is-end{margin-left:auto}
.tour-chrome svg{width:15px;height:15px;fill:none;stroke:var(--ink-3,#9c968c);stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.tour-url{flex:0 1 420px;margin-left:auto;display:flex;align-items:center;justify-content:center;gap:7px;height:26px;padding:0 14px;border-radius:7px;background:var(--ph,#fff);box-shadow:inset 0 0 0 1px var(--ph-line,#e3dfd7);font-weight:400;color:var(--ink-2,#5f5a53);white-space:nowrap;overflow:hidden}
.tour-url svg{width:12px;height:12px}
.tour-chrome[data-kind=app]{height:38px;justify-content:center;position:relative}
.tour-chrome[data-kind=app] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=phone]{height:46px;justify-content:space-between;padding:0 26px;background:transparent;border:0;font:600 15px/1 var(--sans,system-ui);color:var(--ink,#191816)}
.tour-notch{width:120px;height:32px;border-radius:20px;background:#111}
.tour-status{display:flex;gap:4px}.tour-status i{width:16px;height:10px;border-radius:2px;background:var(--ink,#191816)}
[data-chrome=phone]{--tour-win-radius:54px;box-shadow:0 0 0 10px #111,0 0 0 11px #333,0 40px 90px -30px rgba(25,24,22,.55)}
[data-chrome=none]{--tour-win-radius:8px}
/* terminal: a warm charcoal window (tokens --tour-term-bg, --tour-term-bar, --tour-term-ink, --tour-term-dim) */
[data-chrome=terminal]{background:var(--tour-term-bg,#1d1b18);color:var(--tour-term-ink,#ebe5d9)}
.tour-chrome[data-kind=terminal]{height:38px;justify-content:center;position:relative;background:var(--tour-term-bar,#272420);border-bottom:1px solid rgba(255,255,255,.07);color:var(--tour-term-dim,#a39b8e);font-weight:500}
.tour-chrome[data-kind=terminal] .tour-lights{position:absolute;left:14px;top:13px}
.tour-chrome[data-kind=terminal] .tour-lights i{box-shadow:inset 0 0 0 .5px rgba(0,0,0,.3)}
/* windows inside the window: any [data-chrome] element in the product gets its own chrome and frame */
[data-tour-window] [data-chrome]{display:flex;flex-direction:column;overflow:hidden;border-radius:var(--tour-win-radius)}
[data-tour-window] [data-chrome] > :not(.tour-chrome){flex:1;min-height:0}

/* cursor and ripples (stage coordinates) */
.tour-cur{position:absolute;left:0;top:0;z-index:8;width:0;height:0;pointer-events:none;opacity:0;transform-origin:0 0}
.tour-cur svg{position:absolute;left:-1px;top:-1px;overflow:visible;filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.35)) drop-shadow(0 3px 6px rgba(0,0,0,.12))}
.tour-cur .tour-arrow path{fill:#141312;stroke:#fff;stroke-width:1.3}
.tour-cur .tour-hand{left:-8px;top:-2px}
.tour-cur .tour-hand path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-cur .tour-beam{left:-5px;top:-12px}
.tour-cur .tour-beam path{stroke:#141312;stroke-width:1.6;paint-order:stroke}
.tour-cur[data-look=light] .tour-arrow path{fill:#fff;stroke:#141312;stroke-width:1.1}
.tour-ring{position:absolute;left:0;top:0;z-index:7;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;border:2.5px solid var(--tour-ring);background:color-mix(in srgb,var(--tour-ring) 18%,transparent);pointer-events:none;opacity:0}
/* pointer:'touch': a fingertip (44 window px, it zooms with the screen) instead of the arrow; tour.js sets its opacity and size */
.tour-touch{display:none;position:absolute;left:-22px;top:-22px;width:44px;height:44px;border-radius:50%;background:var(--tour-touch,rgba(112,112,120,.36));
  box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.62),0 0 0 1px rgba(20,19,18,.1),0 3px 12px -3px rgba(20,19,18,.32)}
.tour-cur.is-down .tour-touch{background:var(--tour-touch-down,rgba(92,92,100,.48));box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.7),0 0 0 1px rgba(20,19,18,.12),0 1px 5px -1px rgba(20,19,18,.3)}
.is-touch .tour-touch{display:block}
.is-touch .tour-cur svg{display:none!important}
.is-touch .tour-ring{width:44px;height:44px;margin:-22px 0 0 -22px;border:1.5px solid rgba(112,112,120,.55);background:none}
/* more than one pointer (steps with { by: 'agent' }): its own colour (--tour-agent) and a label tag; the person's
   cursor gets a tag too when pointers.main.label is set */
.tour-cur[data-look=agent] .tour-arrow path{fill:var(--tour-agent,#3b4bc8);stroke:#fff;stroke-width:1.4}
.tour-cur[data-look=agent] svg{filter:drop-shadow(0 1px 1.5px rgba(0,0,0,.25)) drop-shadow(0 0 7px color-mix(in srgb,var(--tour-agent,#3b4bc8) 45%,transparent))}
.tour-tag{position:absolute;left:13px;top:21px;display:flex;align-items:center;gap:6px;height:22px;padding:0 8px;border-radius:6px;background:var(--ink,#191816);color:#fff;
  font:600 11.5px/1 var(--sans,system-ui);letter-spacing:.01em;white-space:nowrap;box-shadow:0 4px 12px -4px rgba(0,0,0,.35)}
.tour-tag span{font:500 11px/1 var(--mono,ui-monospace,monospace);opacity:.82}
.tour-tag span[hidden]{display:none}
.tour-cur[data-look=agent] .tour-tag{background:var(--tour-agent,#3b4bc8)}
.tour-ring[data-who]:not([data-who=main]){--tour-ring:var(--tour-agent,#3b4bc8)}

/* chapter card: "02 / 05", a title with one italic word, one line */
.tour-card{position:absolute;z-index:6;left:var(--gutter,32px);bottom:var(--gutter,32px);width:min(calc(var(--su)*44),calc(100% - 2 * var(--gutter,32px)));
  padding:calc(var(--su)*1.8) calc(var(--su)*2.1) calc(var(--su)*2);background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 20px 44px -24px rgba(25,24,22,.45);
  opacity:0;transform:translateY(calc((1 - var(--o,0)) * 10px));pointer-events:none}
.tour-card-n{font:500 max(10.5px,calc(var(--su)*1.15))/1 var(--sans,system-ui);letter-spacing:.14em;color:var(--ink-3,#9c968c)}
.tour-card h3{margin:calc(var(--su)*1) 0 calc(var(--su)*.75);font:400 max(25px,calc(var(--su)*3.7))/1 var(--serif,Georgia,serif);letter-spacing:-.018em;color:var(--ink,#191816)}
.tour-card h3 em{font-style:italic}
.tour-card p{margin:0;font:400 max(13.5px,calc(var(--su)*1.7))/1.45 var(--sans,system-ui);color:var(--ink-2,#5f5a53)}
.tour-card,.tour-cap{transition:translate .55s cubic-bezier(.2,.7,.2,1)}
.tour-card[data-dodge=hide]{opacity:0!important}
.tour-card[data-dodge=off]{display:none}
.tour-card-x{position:absolute;top:calc(var(--su)*.9);right:calc(var(--su)*.9);width:max(26px,calc(var(--su)*2.8));height:max(26px,calc(var(--su)*2.8));display:grid;place-items:center;
  padding:0;border:0;border-radius:50%;background:transparent;color:var(--ink-3,#9c968c);font:400 max(16px,calc(var(--su)*1.9))/1 var(--sans,system-ui);cursor:pointer;pointer-events:auto;opacity:.7}
.tour-card-x:hover{opacity:1;background:var(--ph-line,#e3dfd7);color:var(--ink,#191816)}
.tour-card-x:focus-visible{outline:2px solid var(--tour-ring,#c2643f);outline-offset:2px;opacity:1}
.is-stack .tour-card{left:4%;right:4%;width:auto;bottom:auto;top:var(--card-top);padding:calc(var(--su)*2) calc(var(--su)*2.4)}
[data-tour-root].is-play:not(.is-stack) .tour-card{bottom:calc(var(--gutter,32px) + 46px)}

/* caption line: burned into recordings, because X autoplays muted */
.tour-cap{position:absolute;z-index:7;left:50%;bottom:calc(var(--su)*4);margin:0;max-width:min(calc(var(--su)*72),calc(100% - 2 * var(--gutter,32px)));width:max-content;
  padding:calc(var(--su)*1.05) calc(var(--su)*1.9);border-radius:calc(var(--su)*.6);background:var(--tour-cap-bg);color:var(--tour-cap-ink);
  font:500 max(14px,calc(var(--su)*2.35))/1.3 var(--sans,system-ui);letter-spacing:-.005em;text-align:center;opacity:0;transform:translate(-50%,calc((1 - var(--o,0)) * 8px));pointer-events:none;text-wrap:balance}
.is-stack .tour-cap{bottom:calc(var(--su)*5)}
.is-stack.is-tall .tour-cap{bottom:auto;top:var(--cap-top)}
[data-tour-root].is-play .tour-cap{bottom:calc(var(--su)*4 + 46px)}

/* key caps */
.tour-keys{position:absolute;z-index:7;display:flex;gap:calc(var(--su)*.6);transform:translate(-50%,calc((1 - var(--o,0)) * 8px));opacity:0;pointer-events:none}
.tour-keys kbd{min-width:calc(var(--su)*5.4);height:calc(var(--su)*5.4);padding:0 calc(var(--su)*1.2);display:grid;place-items:center;border-radius:calc(var(--su)*.9);
  background:var(--ph,#fff);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 calc(var(--su)*.35) 0 var(--ph-line,#e3dfd7),0 14px 30px -16px rgba(25,24,22,.5);
  font:500 calc(var(--su)*2.4)/1 var(--sans,system-ui);color:var(--ink,#191816)}

/* play driver: one quiet bar */
.tour-ctl{position:absolute;z-index:9;left:50%;bottom:14px;transform:translateX(-50%);display:flex;align-items:center;gap:12px;width:min(620px,calc(100% - 28px));
  padding:7px 14px 7px 7px;border-radius:999px;background:color-mix(in srgb,var(--ph,#fff) 92%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 12px 30px -18px rgba(25,24,22,.5);
  font:500 11.5px/1 var(--mono,ui-monospace,monospace);color:var(--ink-2,#5f5a53)}
.tour-pp{flex:none;width:32px;height:32px;border:0;border-radius:50%;display:grid;place-items:center;background:var(--ink,#191816);color:var(--page,#f5f3ef);cursor:pointer}
.tour-pp svg{width:13px;height:13px;fill:currentColor}
.tour-pp:focus-visible,.tour-scrub input:focus-visible{outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-scrub{position:relative;flex:1;height:20px;display:flex;align-items:center}
.tour-scrub::before{content:"";position:absolute;left:0;right:0;height:2px;background:var(--ph-line,#e3dfd7)}
.tour-scrub::after{content:"";position:absolute;left:0;height:2px;width:calc(var(--v,0) * 100%);background:var(--ink,#191816)}
.tour-scrub i{position:absolute;top:5px;width:1px;height:10px;background:var(--ink-3,#9c968c)}
.tour-scrub input{position:relative;z-index:1;width:100%;margin:0;background:none;-webkit-appearance:none;appearance:none;cursor:pointer;height:20px}
.tour-scrub input::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;border-radius:50%;background:var(--ink,#191816)}
.tour-scrub input::-moz-range-thumb{width:12px;height:12px;border:0;border-radius:50%;background:var(--ink,#191816)}
.tour-time{flex:none;min-width:84px;text-align:right}
[data-tour-root]:not(.is-begun) .tour-ctl{opacity:0;pointer-events:none}
.tour-ctl{transition:opacity .4s ease}
.is-stack .tour-time{display:none}

/* scroll driver: the auto-play switch, the only way to take over while it plays itself */
.tour-drift{position:absolute;z-index:9;right:var(--gutter,16px);bottom:16px;display:flex;align-items:center;gap:10px;padding:7px 8px 7px 14px;border-radius:999px;
  background:color-mix(in srgb,var(--ph,#fff) 88%,transparent);box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 10px 26px -14px rgba(25,24,22,.45);
  font:500 12px/1 var(--sans,system-ui);color:var(--ink,#191816);cursor:pointer;user-select:none;transition:opacity .5s ease,transform .5s cubic-bezier(.2,.7,.2,1)}
.tour-drift input{position:absolute;opacity:0;pointer-events:none}
.tour-drift > i{position:relative;width:34px;height:20px;border-radius:999px;background:var(--ink,#191816);transition:background-color .25s}
.tour-drift > i::after{content:"";position:absolute;top:3px;left:17px;width:14px;height:14px;border-radius:50%;background:var(--page,#f5f3ef);transition:left .3s cubic-bezier(.2,.7,.2,1)}
.tour-drift:has(input:not(:checked)) > i{background:var(--rule,#d8d3c9)}
.tour-drift:has(input:not(:checked)) > i::after{left:3px}
.tour-drift:has(input:focus-visible){outline:2px solid var(--note,#c2643f);outline-offset:3px}
.tour-drift.is-gone{opacity:0;transform:translateY(8px);pointer-events:none}
.tour-say{position:absolute;right:0;bottom:calc(100% + 10px);width:max-content;max-width:min(260px,calc(100vw - 32px));padding:9px 12px;border-radius:8px;background:var(--ink,#191816);color:var(--page,#f5f3ef);
  font:500 12px/1.35 var(--sans,system-ui);opacity:0;transform:translateY(6px);pointer-events:none;transition:opacity .3s,transform .4s cubic-bezier(.2,.7,.2,1)}
.tour-drift.is-saying .tour-say{opacity:1;transform:none}
.tour-drift.is-saying{box-shadow:0 0 0 1px var(--ph-line,#e3dfd7),0 0 0 4px color-mix(in srgb,var(--note,#c2643f) 35%,transparent)}

/* ?record: a clean stage of the chosen ratio, centred in the browser window, for Monet Shot to record */
html.tour-record,html.tour-record body{height:100%;overflow:hidden;background:#0e0e0d}
html.tour-record body :not([data-tour-root].is-record,[data-tour-root].is-record *,:has([data-tour-root].is-record)){display:none!important}   /* everything but the film (which may sit inside another section) */
html.tour-record .sf-note,html.tour-record .sf-spec,html.tour-record [data-tour-gate],html.tour-record [data-tour-hide-on-record]{display:none!important}
html.tour-record [data-tour-root].is-record{position:fixed;left:50%;top:50%;width:var(--rw);height:var(--rh)!important;transform:translate(-50%,-50%);z-index:2147483000;cursor:none}
html.tour-record .is-record [data-tour-stage]{position:absolute;inset:0;height:auto}

@media (prefers-reduced-motion:reduce){.tour-drift,.tour-drift *,.tour-say{transition:none}}
